const adicionales = $('HTTP Request9').all();
const triggerData = $('Select rows from a table2').first().json;

// Parsear adicionales_solicitados
let adicionales_solicitados = triggerData.adicionales;
if (typeof adicionales_solicitados === 'string') {
  try {
    adicionales_solicitados = JSON.parse(adicionales_solicitados);
  } catch (e) {
    adicionales_solicitados = [];
  }
}
if (!Array.isArray(adicionales_solicitados)) {
  adicionales_solicitados = [];
}

// Verificar si es aeropuerto
const sucursal_nombre = triggerData.sucursal_nombre || '';
const esAeropuerto = sucursal_nombre.toLowerCase().includes('aeropuerto');

// Si es aeropuerto, agregar Tasa Aeropuerto
if (esAeropuerto) {
  const tieneTasaAeropuerto = adicionales_solicitados.some(a => a.Name === 'Tasa Aeropuerto');
  if (!tieneTasaAeropuerto) {
    adicionales_solicitados.push({ Id: 2, Name: 'Tasa Aeropuerto', cantidad: 1 });
  }
}

// Extraer IDs solicitados
const idsSolicitados = adicionales_solicitados.map(a => Number(a.Id));

// Filtrar del listado completo por ID
const resultado = adicionales
  .filter(a => idsSolicitados.includes(Number(a.json.Id)))
  .map(a => ({
    Additional: {
      IsPriceByDay: a.json.IsPriceByDay,
      Price: a.json.Price,
      MaxQuantityPerBooking: a.json.MaxQuantityPerBooking,
      Stock: a.json.Stock,
      Order: a.json.Order,
      Id: a.json.Id
    },
    Quantity: 1
  }));

return [{ json: { additionals: resultado } }];

const items = $input.all();
const allResponses = [];

// Helper para normalizar texto
function norm(txt) {
  return (txt || '').toString().trim().toLowerCase();
}

// Iterar sobre cada item y parsear el campo response
for (const item of items) {
  try {
    const parsed = JSON.parse(item.json.response);

    const nameNormalized = norm(parsed.Name);

    // Filtrar:
    // - Stock > 0
    // - Que NO sea monopatín eléctrico
    if (
      parsed.Stock && 
      parsed.Stock > 0 &&
      !nameNormalized.includes('monopat')
    ) {
      allResponses.push(parsed);
    }

  } catch (error) {
    continue;
  }
}

// Devolver un único objeto con los resultados filtrados
return [
  {
    json: {
      response: allResponses
    }
  }
];

// Obtener todos los items de entrada
const items = $input.all();

// Intentar diferentes formas de acceder a los datos
let searchResults;

// Opción 1: El array está directamente en json
if (Array.isArray(items[0].json)) {
  searchResults = items[0].json;
}
// Opción 2: Hay múltiples items, cada uno es un vehículo
else if (items.length > 1) {
  searchResults = items.map(item => item.json);
}
// Opción 3: El json es un objeto que contiene el array
else {
  searchResults = items[0].json;
}

// Filtrar solo los vehículos disponibles (OnlyQuote: false)
const vehiculosDisponibles = searchResults.filter(vehiculo => {
  return vehiculo && vehiculo.OnlyQuote === false;
});

// Retornar wrapeado en un objeto con la propiedad "vehiculos"
return [{ 
  json: {
    vehiculos: vehiculosDisponibles,
    total: vehiculosDisponibles.length
  }
}];

// Extraer vehículos únicos con datos importantes
const items = $input.all();
const vehicles = new Set();
const output = [];

// Modelos a excluir de la lista
const MODELOS_EXCLUIDOS = [
  "Mercedes Benz SPRINTER Motorhome"
];

items.forEach(item => {
  const data = item.json;

  // Navegar correctamente por la estructura
  if (data.response && Array.isArray(data.response)) {
    data.response.forEach(vehicleData => {
      const model = vehicleData.Car.Model;
      const vehicleId = model.Id;
      const nombreCompleto = `${model.Brand.Name} ${model.Name}`;

      // Filtrar modelos excluidos
      const esExcluido = MODELOS_EXCLUIDOS.some(excluido =>
        nombreCompleto.includes(excluido)
      );
      if (esExcluido) return;

      // Evitar duplicados por ID
      if (!vehicles.has(vehicleId)) {
        vehicles.add(vehicleId);

        output.push({
          id: model.Id,
          nombre: model.Name,
          descripcion: model.Description,
          marca: model.Brand.Name,
          categoria: model.Category.Id,
          pasajeros: model.Passengers,
          puertas: model.Doors,
          transmision: model.Gearbox,
          aireAcondicionado: model.AirConditioner,
          precioTotal: vehicleData.Price,
          precioPorDia: vehicleData.AverageDayPrice,
          dias: vehicleData.TotalDays,
          imagen: model.ImagePath,
          url: vehicleData.WebDeepLink
        });
      }
    });
  }
});

return { response: output };

// Obtener todos los items del input
const data = $input.all();

// La reserva real está en data[0].json
const reserva = data[0].json;

// Función formatear fecha Argentina
function formatearFecha(fechaISO) {
  if (!fechaISO) return null;
  return fechaISO; // Sin transformación
}

// Obtener adicionales
const adicionales = (reserva.Additionals || [])
  .map(a => a.Additional?.Name)
  .filter(Boolean);

// 🔹 Obtener modelo nuevo del auto
const carModel = reserva.Car?.Model ?? null;

// 🔹 Formatear info del modelo (si existe)
let modeloFormateado = null;

if (carModel) {
  modeloFormateado = {
    descripcion: carModel.Description ?? null,
    marca: carModel.Brand?.Name ?? null,
    modelo: carModel.Name ?? null,
    puertas: carModel.Doors ?? null,
    pasajeros: carModel.Passengers ?? null,
    categoria: carModel.Category?.Name ?? null,
  };
}

// Construir respuesta final
const response = {
  numero_reserva: reserva.Id,
  lugar_retiro: reserva.DeliveryPlace?.Name ?? null,
  fecha_hora_retiro: formatearFecha(reserva.FromDate),
  lugar_devolucion: reserva.ReturnPlace?.Name ?? null,
  fecha_hora_devolucion: formatearFecha(reserva.ToDate),

  vehiculo: {
    categoria: reserva.Category?.Name ?? null,
    modelo: modeloFormateado
  },

  adicionales: adicionales.length ? adicionales.join(', ') : 'Sin adicionales',

  valor_reserva: reserva.CustomerPrice ?? reserva.Price ?? null
};

// Devolver en formato requerido
return [
  {
    response
  }
];

const items = $input.all();

items.forEach(item => {
  const data = item.json;
  const priceItems = data.PriceItems || [];

  // Calcular base sobre la que aplica el descuento (Type 0 + TypeId 2 + TypeId 30)
  const baseDescuento = priceItems
    .filter(i => i.Type === 0 || i.TypeId === 2 || i.TypeId === 30)
    .reduce((sum, i) => sum + i.Price, 0);

  const descuento = baseDescuento * 0.20;

  // Total sin IVA, sin descuento
  const totalSinIVA = priceItems
    .filter(i => i.Type !== 15)
    .reduce((sum, i) => sum + i.Price, 0);

  const precioFinal = (totalSinIVA - descuento) * 1.21;

  // Actualizar campos
  data.Price = precioFinal;
  if (data.PriceDetails) {
    data.PriceDetails.Price = precioFinal;
    data.PriceDetails.CustomerPrice = precioFinal;
  }
  if (data.CustomerPrice !== undefined) {
    data.CustomerPrice = precioFinal;
  }
});

return items;

