const data = $input.all();

// La reserva real está en data[0].json
const reserva = data[0].json;

// Función formatear fecha Argentina
function formatearFecha(fechaISO) {
  if (!fechaISO) return null;
  const fecha = new Date(fechaISO);
  return fecha.toLocaleString("es-AR", {
    timeZone: "America/Argentina/Buenos_Aires",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
  });
}

// Obtener adicionales
const adicionales = (reserva.Additionals || [])
  .map(a => a.Additional?.Name)
  .filter(Boolean);

// 🔹 Obtener modelo nuevo del auto
const carModel = reserva.Car?.Model ?? null;

// 🔹 Formatear info del modelo (si existe)
let modeloFormateado = null;

if (carModel) {
  modeloFormateado = {
    descripcion: carModel.Description ?? null,
    marca: carModel.Brand?.Name ?? null,
    modelo: carModel.Name ?? null,
    puertas: carModel.Doors ?? null,
    pasajeros: carModel.Passengers ?? null,
    categoria: carModel.Category?.Name ?? null,
  };
}

// Construir respuesta final
const response = {
  numero_reserva: reserva.Id,
  apellido: $input.first().json.Customer.Lastname,
  lugar_retiro: reserva.DeliveryPlace?.Name ?? null,
  fecha_hora_retiro: formatearFecha(reserva.FromDate),
  lugar_devolucion: reserva.ReturnPlace?.Name ?? null,
  fecha_hora_devolucion: formatearFecha(reserva.ToDate),

  vehiculo: {
    categoria: reserva.Category?.Name ?? null,
    modelo: modeloFormateado
  },

  adicionales: adicionales.length ? adicionales.join(', ') : 'Sin adicionales',

  valor_reserva: reserva.CustomerPrice ?? reserva.Price ?? null
};

// Devolver en formato requerido
return [
  {
    response
  }
];
